// A Cargo build's JS, copied beside each module's Rust (ADR 0101), is
// published as a build's output is (ADR 0091): every byte prepared before
// any file changes, a file removed only if this build wrote it and it's
// still as written, and only the specifiers the compiler found relocated,
// its manifest's `links` (ADR 0101). Each case runs
// `writeInSource` on a build's output made by hand, without Cargo; and the
// builder asks the compiler what it is again once it's replaced.
//
//   build output (target/)            beside the Rust (src/)
//   lib.js  util.js  old.js    ──►    lib.js  util.js  old.js   + the ledger
//   lib.js  util.js            ──►    lib.js  util.js           old.js gone, if as written

import { expect, test } from "bun:test";
import { chmodSync, existsSync, mkdirSync, readFileSync, utimesSync, writeFileSync } from "node:fs";
import { dirname, join, resolve } from "node:path";

import { writeInSource } from "../tooling/cargo.js";
import { appCacheFloor, boundAppCache, cacheDirOf, createNativeBuilder, holdTarget } from "../tooling/build.js";
import { bytesOf } from "../tooling/bounded.js";
import { fixture } from "./support";

const header = (rust: string) => `// Generated by rust-js from ${rust}. Do not edit.\n`;

/** A crate's build output, in `build/`, of modules beside `src/`'s Rust;
 * `imports`, each module's specifiers, at their first place in its JS, as
 * the compiler's parse finds them. */
function crate(dir: string, name: string, modules: Record<string, string>, imports: Record<string, string[]> = {}) {
  mkdirSync(join(dir, "build", name), { recursive: true });
  mkdirSync(join(dir, name, "src"), { recursive: true });
  return {
    library: { name },
    // Its root's Rust, as a manifest has it, a root of `mod`s alone too.
    input: join(dir, name, "src", "lib.rs"),
    modules: Object.entries(modules).map(([module, js]) => {
      const source = join(dir, name, "src", `${module === "" ? "lib" : module}.rs`);
      const file = join(dir, "build", name, `${module === "" ? "lib" : module}.js`);
      writeFileSync(source, "");
      const text = header(source) + js;
      writeFileSync(file, text);
      const links = (imports[module] ?? []).map((specifier) => {
        const start = Buffer.byteLength(text.slice(0, text.indexOf(`"${specifier}"`) + 1));
        return { start, end: start + Buffer.byteLength(specifier), file: resolve(dirname(file), specifier) };
      });
      // Where the compiler says its JS goes in source: beside its Rust.
      return { file, source, module: module === "" ? [] : [module], in_source: source.replace(/\.rs$/, ".js"), links };
    }),
  };
}

test("in source, a file is removed only if this build wrote it, and it's still as written", () => {
  const dir = fixture("in-source-ownership");
  const ledger = join(dir, "build", "in-source.json");
  const src = join(dir, "app", "src");
  writeInSource([crate(dir, "app", { "": "export const a = 1;\n", util: "export const u = 1;\n", old: "export const o = 1;\n" })], ledger);
  // A file rust-js made some other way, `rust-js tool.rs -o src/tool.js`:
  // its header says rust-js, but this build never wrote it.
  writeFileSync(join(src, "tool.js"), header(join(dir, "elsewhere", "tool.rs")) + "export const t = 1;\n");
  writeInSource([crate(dir, "app", { "": "export const a = 1;\n", util: "export const u = 1;\n" })], ledger);
  expect(existsSync(join(src, "old.js"))).toBe(false);
  expect(existsSync(join(src, "tool.js"))).toBe(true);
  // What it writes again, as it was, stays.
  expect(readFileSync(join(src, "util.js"), "utf8")).toContain("export const u = 1;");
  expect(existsSync(join(src, "lib.js"))).toBe(true);
  // One it wrote, edited since: a person's now.
  writeInSource([crate(dir, "app", { "": "export const a = 1;\n", old: "export const o = 1;\n" })], ledger);
  writeFileSync(join(src, "old.js"), readFileSync(join(src, "old.js"), "utf8") + "// mine\n");
  writeInSource([crate(dir, "app", { "": "export const a = 1;\n" })], ledger);
  expect(readFileSync(join(src, "old.js"), "utf8")).toContain("// mine");
  expect(existsSync(join(src, "util.js"))).toBe(false);
});

test("in source, only import specifiers are relocated, not text that reads like one", () => {
  const dir = fixture("in-source-imports");
  const ledger = join(dir, "build", "in-source.json");
  const app = crate(dir, "app", {
    "": 'import { Model } from "../models/lib.js";\n\nexport function main(n) {\n'
      + '  console.log(`text: import { Model } from "../models/lib.js" ${n}`);\n'
      + "  console.log('plain: from \"../models/lib.js\"');\n}\n//# sourceMappingURL=lib.js.map\n",
  }, { "": ["../models/lib.js"] });
  const models = crate(dir, "models", { "": "export const Model = 1;\n" });
  writeInSource([app, models], ledger);
  const js = readFileSync(join(dir, "app", "src", "lib.js"), "utf8");
  expect(js).toContain('import { Model } from "../../models/src/lib.js";\n');
  expect(js).toContain('console.log(`text: import { Model } from "../models/lib.js" ${n}`);');
  expect(js).toContain(`console.log('plain: from "../models/lib.js"');`);
  expect(js.endsWith("//# sourceMappingURL=lib.js.map\n")).toBe(true);
});

test("in source, a build that fails leaves the previous one's files as they were", () => {
  const dir = fixture("in-source-failure");
  const ledger = join(dir, "build", "in-source.json");
  writeInSource([crate(dir, "app", { "": "export const a = 1;\n", util: "export const u = 1;\n" })], ledger);
  const before = readFileSync(join(dir, "app", "src", "lib.js"), "utf8");
  // The next build's root is new, and its other module's map can't be read.
  const next = crate(dir, "app", { "": "export const a = 2;\n", util: "export const u = 2;\n" });
  const util = next.modules.find(m => m.module.length === 1)!;
  writeFileSync(`${util.file}.map`, "{ not json");
  expect(() => writeInSource([{ ...next, modules: next.modules.map(m => m === util ? { ...m, map: `${m.file}.map` } : m) }], ledger)).toThrow();
  expect(readFileSync(join(dir, "app", "src", "lib.js"), "utf8")).toBe(before);
});

test("the builder asks the compiler what it is, and which @rust-js/std it needs", async () => {
  const root = fixture("compiler-identity");
  const std = join(root, "node_modules", "@rust-js", "std");
  mkdirSync(std, { recursive: true });
  writeFileSync(join(std, "package.json"), JSON.stringify({ name: "@rust-js/std", version: "1.0.0" }));
  const rustJs = join(root, "rust-js");
  const compiler = (version: string) => {
    writeFileSync(rustJs, `#!/bin/sh\necho '{"version":"${version}","toolchain":"1.99.0","abi":1}'\n`);
    chmodSync(rustJs, 0o755);
  };
  compiler("1.0.0");
  const builder = createNativeBuilder({ root, rustJs });
  // Its std is installed: what fails is Cargo's, of no manifest.
  const check = (builder: ReturnType<typeof createNativeBuilder>) => builder.checkCargo({ manifestPath: join(root, "Cargo.toml") }).then(() => "built", (error: Error) => error.message);
  expect(await check(builder)).not.toContain("@rust-js/std");
  // Another release, whose std isn't installed.
  compiler("2.0.0");
  expect(await check(createNativeBuilder({ root, rustJs }))).toContain("rust-js 2.0.0 needs @rust-js/std 2.0.0, not the installed 1.0.0");
});

// A manifest of an older compiler's says nothing of where its JS names
// another's, nor where it goes in source: copying it would keep the build's
// names, or guess its place, so it's an error that says to build it again
// (ADR 0101).
test("in source, a build of an older compiler's is built again, not copied", () => {
  const dir = fixture("in-source-older");
  const ledger = join(dir, "build", "in-source.json");
  const app = crate(dir, "app", { "": "export const a = 1;\n" });
  for (const missing of ["links", "in_source"] as const) {
    const older = { ...app, modules: app.modules.map(({ [missing]: _, ...module }) => module) };
    expect(() => writeInSource([older as typeof app], ledger)).toThrow("built by an older rust-js");
  }
  expect(existsSync(join(dir, "app", "src", "lib.js"))).toBe(false);
});

// An app's cache is bounded (#1057, the user's decision of 2026-11-09): a
// target's crates are of one build of the compiler, as Cargo never finds
// another's again, and its targets together are held to a cap, the least
// recently used first, by tooling/bounded.js's one rule.
test("an app's target of another build of the compiler is emptied, but what its builds wrote in source", () => {
  const app = fixture("app-cache-held");
  const target = join(cacheDirOf(app), "target");
  const ledger = join(target, "wasm32-unknown-unknown", "debug", "rust-js-in-source.json");
  const crate = join(target, "wasm32-unknown-unknown", "debug", "deps", "libapp-1111.rmeta");
  mkdirSync(dirname(crate), { recursive: true });
  writeFileSync(crate, "old");
  writeFileSync(ledger, '{"files":[]}');
  // Of no stamp, a cache from before the stamp: emptied.
  holdTarget(app, target, "aaaa");
  expect([existsSync(crate), readFileSync(ledger, "utf8")]).toEqual([false, '{"files":[]}']);
  // Of the same build: kept.
  mkdirSync(dirname(crate), { recursive: true });
  writeFileSync(crate, "aaaa's");
  holdTarget(app, target, "aaaa");
  expect(existsSync(crate)).toBe(true);
  // Of another: emptied, the ledger kept.
  holdTarget(app, target, "bbbb");
  expect([existsSync(crate), readFileSync(ledger, "utf8")]).toEqual([false, '{"files":[]}']);
  // A target of `CARGO_TARGET_DIR`'s, the user's, is never emptied.
  const own = join(fixture("app-cache-users"), "target");
  mkdirSync(own, { recursive: true });
  writeFileSync(join(own, "kept"), "");
  holdTarget(app, own, "aaaa");
  holdTarget(app, own, "bbbb");
  expect(existsSync(join(own, "kept"))).toBe(true);
});

test("an app's cache is held to its cap, the least recently used target first, and none but the one in use below its floor", () => {
  const app = fixture("app-cache-capped");
  const hours = (n: number) => Date.now() / 1000 - n * 60 * 60;
  const target = (purpose: string, used: number) => {
    const at = join(cacheDirOf(app), purpose);
    holdTarget(app, at, "aaaa");
    writeFileSync(join(at, "crates"), Buffer.alloc(64 * 1024));
    utimesSync(join(at, "rust-js-compiler"), used, used);
    return at;
  };
  const oldest = target("clippy", hours(3));
  const older = target("test", hours(2));
  const editor = target("editor", hours(1));
  const own = target("target", hours(0));
  const each = bytesOf(own);
  // The one in use and two more fit: the least recently used goes.
  expect(boundAppCache(app, own, { cap: 3 * each + each / 2, free: () => Number.POSITIVE_INFINITY })).toBe(1);
  expect([oldest, older, editor, own].map(existsSync)).toEqual([false, true, true, true]);
  // Below the floor, each but the one in use goes.
  expect(boundAppCache(app, own, { free: () => appCacheFloor - 1 })).toBe(2);
  expect([older, editor, own].map(existsSync)).toEqual([false, false, true]);
  // A target of `CARGO_TARGET_DIR`'s holds nothing of the app's cache.
  const users = join(fixture("app-cache-capped-users"), "target");
  mkdirSync(users, { recursive: true });
  expect(boundAppCache(app, users, { cap: 0, free: () => 0 })).toBe(0);
  expect(existsSync(own)).toBe(true);
});
